command:
/* Create Thrall (Necromancer)
 * Creates a single thrall token in the nearest unoccupied square to the commanding necromancer.
 * Press the macro again for each additional thrall.
 */

const THRALL_IMG = "icons/magic/death/hand-dirt-undead-zombie.webp";
const PUBLICATION = { license: "ORC", remaster: true, title: "Pathfinder Impossible Magic" };
const THRALL_RANGE_FEET = 30;

const THRALL_RULES =
    "<p>A thrall is a level -1 creature with the mindless and undead traits. It's not a minion, nor does it have the summoned trait. It has 1 Hit Point and is immune to bleed, death effects, disease, mental, and poison. Thralls automatically fail all checks, and any check made against a thrall automatically succeeds. They can take actions only when commanded to by a grave spell or necromancer ability. A thrall is temporary and is destroyed after 1 minute if no other duration is listed.</p>" +
    "<p>A thrall is Medium. It must be created in an unoccupied space or the spell or ability that created the thrall fails. A thrall can contribute to flanking as though it were able to make melee unarmed Strikes. Thralls can't hold their ground&mdash;a creature can move into a thrall's space as though it were unoccupied. The thrall's space is difficult terrain, and the moving creature can automatically push the thrall into an adjacent space that's not in its path.</p>";

/* -------------------------------------------- */
/*  Commanding necromancer                      */
/* -------------------------------------------- */

const commanderToken = canvas.tokens.controlled[0] ?? token ?? null;
const commander = commanderToken?.actor ?? actor ?? game.user.character ?? null;

if (!commanderToken) {
    ui.notifications.error("Select the token of the creature creating the thrall.");
    return;
}

if (!game.user.can("TOKEN_CREATE")) {
    ui.notifications.error("You lack permission to create tokens. Ask your GM to run this macro or grant the permission.");
    return;
}

/** The highest spell attack modifier available to the commanding creature. */
const spellAttackMod = (() => {
    const mods = (commander?.spellcasting?.contents ?? [])
        .flatMap((entry) => entry.statistic ?? [])
        .map((statistic) => statistic.check.mod)
        .filter((mod) => Number.isInteger(mod));
    return mods.length > 0 ? Math.max(...mods) : null;
})();

if (spellAttackMod === null) {
    ui.notifications.warn(`${commander?.name ?? "The selected actor"} has no spell attack modifier: the thrall's Strike will be built at +0.`);
}

// 1d6 at 1st level, increasing by 1d6 at 5th level and every 4 levels thereafter.
const strikeDice = 1 + Math.max(0, Math.floor(((commander?.level ?? 1) - 1) / 4));

/* -------------------------------------------- */
/*  Base thrall actor                           */
/* -------------------------------------------- */

/** Locate the reusable "Thrall" actor, creating it on first use. */
async function getThrallActor() {
    const existing = game.actors.find((a) => a.type === "npc" && a.getFlag("world", "thrall") === true);
    if (existing) return existing;

    if (!game.user.can("ACTOR_CREATE")) {
        ui.notifications.error("The Thrall actor doesn't exist yet. Ask your GM to run this macro once to create it.");
        return null;
    }

    return Actor.create({
        name: "Thrall",
        type: "npc",
        img: THRALL_IMG,
        flags: { world: { thrall: true } },
        system: {
            abilities: {
                cha: { mod: -5 },
                con: { mod: 0 },
                dex: { mod: 0 },
                int: { mod: -5 },
                str: { mod: 0 },
                wis: { mod: 0 },
            },
            attributes: {
                ac: { details: "any check made against a thrall automatically succeeds", value: 0 },
                allSaves: { value: "thralls automatically fail all checks" },
                hp: { details: "", max: 1, temp: 0, value: 1 },
                immunities: [
                    { exceptions: [], type: "bleed" },
                    { exceptions: [], type: "death-effects" },
                    { exceptions: [], type: "disease" },
                    { exceptions: [], type: "mental" },
                    { exceptions: [], type: "poison" },
                ],
                speed: { otherSpeeds: [], value: 15 },
            },
            details: {
                blurb: "",
                languages: { details: "", value: [] },
                level: { value: -1 },
                privateNotes: "",
                publicNotes: THRALL_RULES,
                publication: PUBLICATION,
            },
            initiative: { statistic: "perception" },
            perception: { details: "", mod: 0, senses: [] },
            resources: {},
            saves: {
                fortitude: { saveDetail: "", value: 0 },
                reflex: { saveDetail: "", value: 0 },
                will: { saveDetail: "", value: 0 },
            },
            skills: {},
            traits: { rarity: "common", size: { value: "med" }, value: ["mindless", "undead"] },
        },
        items: [
            {
                name: "Thrall",
                type: "action",
                img: "systems/pf2e/icons/actions/Passive.webp",
                system: {
                    actionType: { value: "passive" },
                    actions: { value: null },
                    category: "defensive",
                    description: { value: THRALL_RULES },
                    publication: PUBLICATION,
                    rules: [],
                    slug: "thrall",
                    traits: { rarity: "common", value: [] },
                },
            },
        ],
        prototypeToken: {
            name: "Thrall",
            actorLink: false,
            disposition: CONST.TOKEN_DISPOSITIONS.FRIENDLY,
            height: 1,
            width: 1,
            sight: { enabled: false },
            texture: { src: THRALL_IMG },
        },
    });
}

/* -------------------------------------------- */
/*  Placement                                   */
/* -------------------------------------------- */

/** Every grid offset currently covered by a token, keyed as "row.column". */
function occupiedOffsets() {
    const occupied = new Set();
    for (const placeable of canvas.tokens.placeables) {
        const doc = placeable.document;
        const origin = canvas.grid.getOffset({ x: doc.x, y: doc.y });
        for (let i = 0; i < Math.ceil(doc.height); i++) {
            for (let j = 0; j < Math.ceil(doc.width); j++) {
                occupied.add(`${origin.i + i}.${origin.j + j}`);
            }
        }
    }
    return occupied;
}

/** The unoccupied offset closest to the commanding token, searching outward ring by ring. */
function findUnoccupiedOffset() {
    const occupied = occupiedOffsets();
    const origin = canvas.grid.getOffset({ x: commanderToken.document.x, y: commanderToken.document.y });
    const maxRings = Math.max(1, Math.floor(THRALL_RANGE_FEET / canvas.scene.grid.distance));

    for (let ring = 1; ring <= maxRings; ring++) {
        for (let i = -ring; i <= ring; i++) {
            for (let j = -ring; j <= ring; j++) {
                if (Math.max(Math.abs(i), Math.abs(j)) !== ring) continue;
                const offset = { i: origin.i + i, j: origin.j + j };
                if (!occupied.has(`${offset.i}.${offset.j}`)) return offset;
            }
        }
    }
    return null;
}

/* -------------------------------------------- */
/*  Execution                                   */
/* -------------------------------------------- */

const thrallActor = await getThrallActor();
if (!thrallActor) return;

const offset = findUnoccupiedOffset();
if (!offset) {
    ui.notifications.error(`No unoccupied space within ${THRALL_RANGE_FEET} feet: the thrall isn't created.`);
    return;
}

const { x, y } = canvas.grid.getTopLeftPoint(offset);
const tokenDocument = await thrallActor.getTokenDocument({
    x,
    y,
    actorLink: false,
    disposition: commanderToken.document.disposition,
});

const [created] = await canvas.scene.createEmbeddedDocuments("Token", [tokenDocument.toObject()]);
if (!created) return;

// The thrall's Strike uses the necromancer's spell attack modifier and level-scaled damage.
await created.actor?.createEmbeddedDocuments("Item", [
    {
        name: "Fist",
        type: "melee",
        img: "systems/pf2e/icons/default-icons/melee.svg",
        system: {
            attack: { value: "" },
            attackEffects: { custom: "", value: [] },
            bonus: { value: spellAttackMod ?? 0 },
            damageRolls: {
                [foundry.utils.randomID()]: { damage: `${strikeDice}d6`, damageType: "bludgeoning" },
            },
            description: {
                value: `<p>Commanded by ${commander ? `@UUID[${commander.uuid}]{${commander.name}}` : "the necromancer"}. This Strike uses and counts toward the necromancer's multiple attack penalty, and may instead deal piercing or slashing damage.</p>`,
            },
            publication: PUBLICATION,
            range: null,
            rules: [],
            slug: null,
            traits: { rarity: "common", value: ["unarmed"] },
        },
    },
    {
        name: "Effect: Thrall",
        type: "effect",
        img: THRALL_IMG,
        system: {
            description: { value: "<p>This thrall is destroyed when this effect expires, unless another duration was listed.</p>" },
            duration: { expiry: "turn-start", sustained: false, unit: "minutes", value: 1 },
            level: { value: Math.max(1, commander?.level ?? 1) },
            publication: PUBLICATION,
            rules: [],
            start: { initiative: null, value: game.time.worldTime },
            tokenIcon: { show: false },
            traits: { rarity: "common", value: [] },
        },
    },
]);

ui.notifications.info(`Thrall created: Strike +${spellAttackMod ?? 0}, ${strikeDice}d6 damage, destroyed after 1 minute.`);
